// The Worker entry (`main` in wrangler.jsonc). It wraps the OpenNext worker and
// answers preview-build downloads itself.
//
// Why not a Next route: a route handler pipes the file through JavaScript, and
// on a ~100 MB build the Worker ran out of CPU time and cut the download short
// after a few hundred kilobytes. Returning the R2 body from here hands the
// stream to the runtime, which copies it without running any script.

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by the OpenNext build.
import openNextWorker from "./.open-next/worker.js";
import { previewDownloadHeaders, previewObjectKey } from "./src/lib/preview-paths";

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by the OpenNext build.
export * from "./.open-next/worker.js";

type PreviewBody = { body: ReadableStream; httpEtag: string };
type WorkerEnv = { PREVIEW_BUILDS?: { get(key: string): Promise<PreviewBody | null> } };
type Fetch = (request: Request, env: WorkerEnv, ctx: unknown) => Promise<Response>;

const worker: { fetch: Fetch } = {
  async fetch(request, env, ctx) {
    if (request.method === "GET" && env.PREVIEW_BUILDS) {
      const key = previewObjectKey(new URL(request.url).pathname);
      if (key) {
        const build = await env.PREVIEW_BUILDS.get(key);
        if (!build) return new Response("Not found.", { status: 404 });
        const fileName = key.slice(key.indexOf("/") + 1);
        return new Response(build.body, { headers: previewDownloadHeaders(fileName, build.httpEtag) });
      }
    }
    return (openNextWorker as { fetch: Fetch }).fetch(request, env, ctx);
  },
};

export default worker;
